package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen0Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector to multiply: [ 1, 0, 2 ]
        // Expected result:
        // row 0: 1*1 + 2*0 + 3*2 = 7
        // row 1: 4*1 + 5*0 + 6*2 = 16
        BigDecimal[] v = {new BigDecimal("1"), new BigDecimal("0"), new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("7"), new BigDecimal("16")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{new BigDecimal("5")}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("10")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ZeroMatrix() {
        BigDecimal[][] data = {
            {BigDecimal.ZERO, BigDecimal.ZERO},
            {BigDecimal.ZERO, BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("10"), new BigDecimal("20")};
        BigDecimal[] expected = {BigDecimal.ZERO, BigDecimal.ZERO};

        BigDecimal[] result = matrix.operate(v);

        // Using compareTo for BigDecimal because scale might differ (0 vs 0.0)
        Assert.assertEquals(0, expected[0].compareTo(result[0]));
        Assert.assertEquals(0, expected[1].compareTo(result[1]));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_TooShort() {
        // Matrix is 2x2
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);
        // Vector is length 1
        BigDecimal[] v = {new BigDecimal("1")};

        matrix.operate(v);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_TooLong() {
        // Matrix is 2x2
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);
        // Vector is length 3
        BigDecimal[] v = {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")};

        matrix.operate(v);
    }

    @Test
    public void testOperate_LargeValues() {
        BigDecimal val1 = new BigDecimal("1000000000000000000");
        BigDecimal val2 = new BigDecimal("2000000000000000000");

        BigDecimal[][] data = {{val1, val2}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {new BigDecimal("2"), new BigDecimal("3")};
        // (1e18 * 2) + (2e18 * 3) = 2e18 + 6e18 = 8e18
        BigDecimal expectedVal = new BigDecimal("8000000000000000000");

        BigDecimal[] result = matrix.operate(v);

        Assert.assertEquals(0, expectedVal.compareTo(result[0]));
    }
}
